  <script>
$(document).ready(function() {
   $('#app').click(function() {
        $('body').append('<div class="overlay"></div>');
    $(".app").css("display", "block");
    setTimeout(function() {
      $(".app").css("opacity", "0.7");
       }, 3);
        setTimeout(function() {
      $(".app").css("opacity", "0");
    }, 2000);
     $(".app").on("transitionend webkitTransitionEnd oTransitionEnd MSTransitionEnd", function() {
      $(this).css({
        display: "none",
        opacity: 0
      });
       $(".overlay").remove();
    });
  });
 });
</script>
<script>
$(document).ready(function(){
        $('.withdraw').click(function(event){
               event.preventDefault();
        $.ajax({
        url: "{{route('wallet.withdraw-money')}}",
        type: 'GET',
        dataType: 'json',
        success: function(data) {
               console.log(data);
            if(data.redirect){
              swal({
        title: 'Warning',
        text: 'You have not added your bank details yet. Please add them now.',
        icon: 'warning',
       
        showConfirmButton: true,
    }).then(() => {
        window.location.replace("{{ route('user.withdraw-method')}}");
    });
            }
        },
        error: function() {
            console.log('test');
        }
        });
    });
});
</script>
